package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

/** Emulator-only real labels/SQLite/native UI, fake playback provider, no device effects. */
public class SoundLabelFlowTest {
    @org.junit.Rule public final SoundBrowseTestScope browseScope=new SoundBrowseTestScope();
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private UiObject2 object(BySelector selector){UiObject2 found=device.wait(Until.findObject(selector),5000);assertNotNull(selector.toString(),found);return found;}
    private Activity focused(Class<?> kind,Activity previous){long until=SystemClock.elapsedRealtime()+5000;Activity[] found={null};while(found[0]==null){i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(kind.isInstance(a)&&a!=previous&&a.hasWindowFocus()&&a.getWindow().getDecorView().isAttachedToWindow())found[0]=a;});assertTrue("Focused selector frame",found[0]!=null||SystemClock.elapsedRealtime()<until);if(found[0]==null)SystemClock.sleep(25);}return found[0];}
    private void capture(Harness h,String name,Class<?> kind)throws Exception{Activity a=focused(kind,null);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View v=a.getWindow().getDecorView();v.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);v.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();assertTrue(device.takeScreenshot(new File(h.folder,name+".png")));}
    private final class Harness implements AutoCloseable {
        final SoundLabelFixture fixture;final Records.Factory prior=Records.factory;final ClipPlayback.Provider playback=ClipPlayback.provider;final SoundLabelJob.Factory jobFactory=SoundLabelJob.factory;final Map<String,?> prefs=Prefs.of(c).getAll();final List<Activity> owned=new CopyOnWriteArrayList<>();final List<SoundLibraryUiTest.FakePort> ports=new CopyOnWriteArrayList<>();final File folder=new File(c.getExternalFilesDir(null),"verification");
        final Application app=(Application)c.getApplicationContext();final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof SoundEventsActivity||a instanceof SoundLabelActivity||a instanceof FavoriteSoundsActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
        Harness()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));fixture=new SoundLabelFixture(c);assertTrue(folder.isDirectory()||folder.mkdirs());app.registerActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=context->new Store(context,fixture.database);ClipPlayback.provider=(context,records)->{SoundLibraryUiTest.FakePort port=new SoundLibraryUiTest.FakePort();ports.add(port);return port;};});}
        void start(){c.startActivity(new Intent(c,SoundEventsActivity.class).putExtra("record",1L).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic sound labels · no audio output").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
        String key(){try(Store store=fixture.open()){return "event:"+fixture.event(store).optLong("id");}}
        void diagnostic(Throwable failure){try{device.takeScreenshot(new File(folder,"sound-label-failure.png"));device.dumpWindowHierarchy(new File(folder,"sound-label-failure.xml"));}catch(Exception e){failure.addSuppressed(e);}}
        public void close()throws Exception{boolean drained=false;try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});long until=SystemClock.elapsedRealtime()+5000;for(Activity a:owned){boolean[] destroyed={false};while(!destroyed[0]){i.runOnMainSync(()->destroyed[0]=a.isDestroyed());assertTrue("Owned Activity teardown",destroyed[0]||SystemClock.elapsedRealtime()<until);if(!destroyed[0])SystemClock.sleep(25);}assertTrue(a instanceof SoundLabelActivity?((SoundLabelActivity)a).awaitReaders(5000):a instanceof FavoriteSoundsActivity?((FavoriteSoundsActivity)a).awaitReaders(5000):((SoundEventsActivity)a).awaitReaders(5000));}for(SoundLibraryUiTest.FakePort port:ports)assertTrue(port.sessions.isEmpty());drained=true;}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=prior;ClipPlayback.provider=playback;SoundLabelJob.factory=jobFactory;});if(drained)fixture.close();assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}}
    }
    @Test public void selectCancelRecreateSaveResetAndAlbumReopenUseRealPersistedLabels()throws Exception{
        try(Harness h=new Harness()){try{h.start();object(By.desc("Correct label "+h.key()));capture(h,"sound-label-source",SoundEventsActivity.class);object(By.desc("Correct label "+h.key())).click();object(By.desc("Label: Use original estimate").selected(true));capture(h,"sound-label-selector",SoundLabelActivity.class);object(By.desc("Label: Speech")).click();object(By.desc("Label: Speech").selected(true));capture(h,"sound-label-draft",SoundLabelActivity.class);Activity first=focused(SoundLabelActivity.class,null);i.runOnMainSync(first::recreate);focused(SoundLabelActivity.class,first);object(By.desc("Label: Speech").selected(true));try(Store store=h.fixture.open()){assertTrue(h.fixture.event(store).isNull("user_category"));}capture(h,"sound-label-draft-recreated",SoundLabelActivity.class);object(By.text("Cancel").enabled(true)).click();object(By.desc("Correct label "+h.key()));object(By.text("Snoring estimate"));capture(h,"sound-label-cancelled",SoundEventsActivity.class);
            object(By.desc("Correct label "+h.key())).click();object(By.desc("Label: Speech")).click();object(By.text("Save label").enabled(true)).click();object(By.text("Speech · Your label"));object(By.desc("Snoring (0)"));capture(h,"sound-label-corrected",SoundEventsActivity.class);object(By.desc("Correct label "+h.key())).click();object(By.desc("Label: Speech").selected(true));capture(h,"sound-label-reopened",SoundLabelActivity.class);object(By.desc("Label: Use original estimate")).click();object(By.text("Save label").enabled(true)).click();object(By.text("Snoring estimate"));capture(h,"sound-label-reset",SoundEventsActivity.class);
            object(By.desc("Sound event options")).click();object(By.text("Favorite sounds")).click();object(By.desc("Correct label "+h.key())).click();object(By.desc("Label: Speech")).click();object(By.text("Save label").enabled(true)).click();object(By.text("Speech · Your label"));object(By.desc("Speech (1)"));capture(h,"sound-label-album",FavoriteSoundsActivity.class);try(Store store=h.fixture.open()){assertEquals("snoring",h.fixture.event(store).getString("category"));assertEquals("speech",h.fixture.event(store).getString("user_category"));assertEquals(1,h.fixture.event(store).getInt("favorite"));assertEquals(2,ReportSounds.read(c,store,Records.get(store,1)).speech);}assertTrue(h.fixture.file.exists());
        }catch(Throwable failure){h.diagnostic(failure);throw failure;}}
    }
    @Test public void trimAndDeletedRowHaveVisibleErrorsWithoutChangingEvidence()throws Exception{
        try(Harness h=new Harness()){try{h.start();object(By.desc("Correct label "+h.key())).click();object(By.desc("Label: Speech")).click();Intent[] stale={null};i.runOnMainSync(()->stale[0]=new Intent(focusedOnMain()));try(Store store=h.fixture.open()){RecordEntry night=Records.get(store,1);Records.save(store,1,new RecordDraft(h.fixture.start+5000,h.fixture.start+10000),night.updated,System.currentTimeMillis());}object(By.text("Save label").enabled(true)).click();object(By.text("The sleep period changed. Reopen the sound event."));capture(h,"sound-label-trim-error",SoundLabelActivity.class);Activity changed=focused(SoundLabelActivity.class,null);i.runOnMainSync(changed::recreate);focused(SoundLabelActivity.class,changed);object(By.text("The sleep period changed. Reopen the sound event."));capture(h,"sound-label-trim-error-recreated",SoundLabelActivity.class);object(By.text("Cancel").enabled(true)).click();focused(SoundEventsActivity.class,null);
            try(Store store=h.fixture.open()){assertTrue(h.fixture.event(store).isNull("user_category"));store.getWritableDatabase().delete("sound_events","id=?",new String[]{""+h.fixture.event(store).getLong("id")});}c.startActivity(stale[0].addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));object(By.text("This sound event changed. Reopen the night."));assertFalse(device.hasObject(By.text("Save label")));capture(h,"sound-label-deleted-error",SoundLabelActivity.class);object(By.text("Try again")).click();object(By.text("This sound event changed. Reopen the night."));capture(h,"sound-label-deleted-retry",SoundLabelActivity.class);assertTrue(h.fixture.file.exists());
        }catch(Throwable failure){h.diagnostic(failure);throw failure;}}
    }
    private Intent focusedOnMain(){for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof SoundLabelActivity)return a.getIntent();throw new AssertionError("Selector not resumed");}
    @Test public void busySaveIsRetainedAndFailureRetryUsesPinnedDatabaseFactory()throws Exception{
        CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger saves=new AtomicInteger();try(Harness h=new Harness()){try{
            i.runOnMainSync(()->SoundLabelJob.factory=(context,records)->new SoundLabelJob.Work(){public void load(SoundLabels.Snapshot request){try(Store store=records.open(context)){SoundLabels.check(store,request);}}public void save(SoundLabels.Snapshot request,String category)throws Exception{int count=saves.incrementAndGet();if(count==1){entered.countDown();if(!release.await(30,TimeUnit.SECONDS))throw new IOException("Fixture timeout");throw new IOException("Injected database failure");}try(Store store=records.open(context)){SoundLabels.save(store,request,category);}}});h.start();object(By.desc("Correct label "+h.key())).click();object(By.desc("Label: Speech")).click();object(By.text("Save label").enabled(true)).click();assertTrue(entered.await(5,TimeUnit.SECONDS));object(By.text("Saving…").enabled(false));capture(h,"sound-label-busy",SoundLabelActivity.class);Activity first=focused(SoundLabelActivity.class,null);i.runOnMainSync(()->{Records.factory=context->{throw new AssertionError("Retained job rebound to global factory");};first.recreate();});focused(SoundLabelActivity.class,first);object(By.text("Saving…").enabled(false));assertTrue(device.hasObject(By.desc("Label: Speech").enabled(false)));assertEquals(1,saves.get());capture(h,"sound-label-busy-recreated",SoundLabelActivity.class);release.countDown();object(By.text("Label could not be saved. Try again."));capture(h,"sound-label-error",SoundLabelActivity.class);Activity error=focused(SoundLabelActivity.class,null);i.runOnMainSync(error::recreate);focused(SoundLabelActivity.class,error);object(By.text("Label could not be saved. Try again."));capture(h,"sound-label-error-recreated",SoundLabelActivity.class);
            // Restore only the album reader; the retained mutation still holds its original factory.
            i.runOnMainSync(()->Records.factory=context->new Store(context,h.fixture.database));object(By.text("Save label").enabled(true)).click();object(By.text("Speech · Your label"));assertEquals(2,saves.get());capture(h,"sound-label-retried",SoundEventsActivity.class);
        }catch(Throwable failure){h.diagnostic(failure);throw failure;}finally{release.countDown();}}
    }
}
